begin;
with j as (select * from jsonb_to_recordset($law7d0034$[{"code_id":"GK_RF_2","article_number":"635","version_date":"1994-11-30","article_text":"1. Предоставляемые арендатору арендодателем услуги по управлению и технической эксплуатации транспортного средства должны обеспечивать его нормальную и безопасную эксплуатацию в соответствии с целями аренды, указанными в договоре. Договором аренды транспортного средства с экипажем может быть предусмотрен более широкий круг услуг, предоставляемых арендатору.\n\n2. Состав экипажа транспортного средства и его квалификация должны отвечать обязательным для сторон правилам и условиям договора, а если обязательными для сторон правилами такие требования не установлены, требованиям обычной практики эксплуатации транспортного средства данного вида и условиям договора.\n\nЧлены экипажа являются работниками арендодателя. Они подчиняются распоряжениям арендодателя, относящимся к управлению и технической эксплуатации, и распоряжениям арендатора, касающимся коммерческой эксплуатации транспортного средства.\n\nЕсли договором аренды не предусмотрено иное, расходы по оплате услуг членов экипажа, а также расходы на их содержание несет арендодатель.","article_title":"Статья 635. Обязанности арендодателя по управлению и технической эксплуатации транспортного средства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7ab8b1b9e92a02ebb206eceffadc34903add0ea7a08214e788e210b5b78d885f"},{"code_id":"GK_RF_2","article_number":"636","version_date":"1994-11-30","article_text":"Если иное не предусмотрено договором аренды транспортного средства с экипажем, арендатор несет расходы, возникающие в связи с коммерческой эксплуатацией транспортного средства, в том числе расходы на оплату топлива и других расходуемых в процессе эксплуатации материалов и на оплату сборов.","article_title":"Статья 636. Обязанность арендатора по оплате расходов, связанных с коммерческой эксплуатацией транспортного средства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86cd9d009fbbff4e10e7f4503626552ee21d7cc833e33ab1a452642d70762cae"},{"code_id":"GK_RF_2","article_number":"637","version_date":"1994-11-30","article_text":"Если иное не предусмотрено договором аренды транспортного средства с экипажем, обязанность страховать транспортное средство и (или) страховать ответственность за ущерб, который может быть причинен им или в связи с его эксплуатацией, возлагается на арендодателя в тех случаях, когда такое страхование является обязательным в силу закона или договора.","article_title":"Статья 637. Страхование транспортного средства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d9d4d57fb11b13d56df241f0472bdae55b79e0765ec9f04c4ef248a3256ad16a"},{"code_id":"GK_RF_2","article_number":"638","version_date":"1994-11-30","article_text":"1. Если договором аренды транспортного средства с экипажем не предусмотрено иное, арендатор вправе без согласия арендодателя сдавать транспортное средство в субаренду.\n\n2. Арендатор в рамках осуществления коммерческой эксплуатации арендованного транспортного средства вправе без согласия арендодателя от своего имени заключать с третьими лицами договоры перевозки и иные договоры, если они не противоречат целям использования транспортного средства, указанным в договоре аренды, а если такие цели не установлены, назначению транспортного средства.","article_title":"Статья 638. Договоры с третьими лицами об использовании транспортного средства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5c496f70042e5a1fcf06abe3ea55bac60626b69378fa3b88a98a73e2d3f357f3"},{"code_id":"GK_RF_2","article_number":"639","version_date":"1994-11-30","article_text":"В случае гибели или повреждения арендованного транспортного средства арендатор обязан возместить арендодателю причиненные убытки, если последний докажет, что гибель или повреждение транспортного средства произошли по обстоятельствам, за которые арендатор отвечает в соответствии с законом или договором аренды.","article_title":"Статья 639. Ответственность за вред, причиненный транспортному средству","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a59eabbd830445e45aea4009d358a841cf099f7f8797df841691b9298b740e0d"},{"code_id":"GK_RF_2","article_number":"640","version_date":"1994-11-30","article_text":"Ответственность за вред, причиненный третьим лицам арендованным транспортным средством, его механизмами, устройствами, оборудованием, несет арендодатель в соответствии с правилами, предусмотренными главой 59 настоящего Кодекса. Он вправе предъявить к арендатору регрессное требование о возмещении сумм, выплаченных третьим лицам, если докажет, что вред возник по вине арендатора.","article_title":"Статья 640. Ответственность за вред, причиненный транспортным средством","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a8f728efc3923d4919c86eb7956ecd9f2fbfbb85b0ccddc7141f8c5c7e121c3b"},{"code_id":"GK_RF_2","article_number":"641","version_date":"1994-11-30","article_text":"Транспортными уставами и кодексами могут быть установлены иные, помимо предусмотренных настоящим параграфом, особенности аренды отдельных видов транспортных средств с предоставлением услуг по управлению и технической эксплуатации.","article_title":"Статья 641. Особенности аренды отдельных видов транспортных средств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9f120bdb9e77288c22a49f083b816677c1dfc98e85f01abf89aa343e796cb401"},{"code_id":"GK_RF_2","article_number":"642","version_date":"1994-11-30","article_text":"По договору аренды транспортного средства без экипажа арендодатель предоставляет арендатору транспортное средство за плату во временное владение и пользование без оказания услуг по управлению им и его технической эксплуатации.\n\nПравила о возобновлении договора аренды на неопределенный срок и о преимущественном праве арендатора на заключение договора аренды на новый срок (статья 621) к договору аренды транспортного средства без экипажа не применяются.","article_title":"Статья 642. Договор аренды транспортного средства без экипажа","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0eb8145d7ff4cdc163ef5b137a8446ccaabd60aabdb5c4c45c8231057b1073da"},{"code_id":"GK_RF_2","article_number":"643","version_date":"1994-11-30","article_text":"Договор аренды транспортного средства без экипажа должен быть заключен в письменной форме независимо от его срока. К такому договору не применяются правила о регистрации договоров аренды, предусмотренные пунктом 2 статьи 609 настоящего Кодекса.","article_title":"Статья 643. Форма договора аренды транспортного средства без экипажа","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7246660edd4d213a31a2a56988769c0fdbe2ee7c1bc4d5136ba7e5220259a15a"},{"code_id":"GK_RF_2","article_number":"644","version_date":"1994-11-30","article_text":"Арендатор в течение всего срока договора аренды транспортного средства без экипажа обязан поддерживать надлежащее состояние арендованного транспортного средства, включая осуществление текущего и капитального ремонта.","article_title":"Статья 644. Обязанность арендатора по содержанию транспортного средства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"41c781ad2ca72cdd8ee8d073b984f5752d478b8bbf8137f31ab5ae111bcd662c"},{"code_id":"GK_RF_2","article_number":"645","version_date":"1994-11-30","article_text":"Арендатор своими силами осуществляет управление арендованным транспортным средством и его эксплуатацию, как коммерческую, так и техническую.","article_title":"Статья 645. Обязанности арендатора по управлению транспортным средством и по его технической эксплуатации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c78e1af3f3db90103805f7a3fa04235682ae79b7964baffa106cc1693732334f"},{"code_id":"GK_RF_2","article_number":"646","version_date":"1994-11-30","article_text":"Если иное не предусмотрено договором аренды транспортного средства без экипажа, арендатор несет расходы на содержание арендованного транспортного средства, его страхование, включая страхование своей ответственности, а также расходы, возникающие в связи с его эксплуатацией.","article_title":"Статья 646. Обязанность арендатора по оплате расходов на содержание транспортного средства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"254e62727db45480750a5671cfd6f69e794ac4ed32693ba715d8f048a9f9c767"},{"code_id":"GK_RF_2","article_number":"647","version_date":"1994-11-30","article_text":"1. Если договором аренды транспортного средства без экипажа не предусмотрено иное, арендатор вправе без согласия арендодателя сдавать арендованное транспортное средство в субаренду на условиях договора аренды транспортного средства с экипажем или без экипажа.\n\n2. Арендатор вправе без согласия арендодателя от своего имени заключать с третьими лицами договоры перевозки и иные договоры, если они не противоречат целям использования транспортного средства, указанным в договоре аренды, а если такие цели не установлены, назначению транспортного средства.","article_title":"Статья 647. Договоры с третьими лицами об использовании транспортного средства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"124210ebf54760d93258dc70bc3183c873f83113f69ccf520d136ad6cff89af3"},{"code_id":"GK_RF_2","article_number":"648","version_date":"1994-11-30","article_text":"Ответственность за вред, причиненный третьим лицам транспортным средством, его механизмами, устройствами, оборудованием, несет арендатор в соответствии с правилами главы 59 настоящего Кодекса.","article_title":"Статья 648. Ответственность за вред, причиненный транспортным средством","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3e6dee0893610b1a163ab74766782d09392507161f5151e1619dbfc2f1461d52"},{"code_id":"GK_RF_2","article_number":"649","version_date":"1994-11-30","article_text":"Транспортными уставами и кодексами могут быть установлены иные, помимо предусмотренных настоящим параграфом, особенности аренды отдельных видов транспортных средств без предоставления услуг по управлению и технической эксплуатации.","article_title":"Статья 649. Особенности аренды отдельных видов транспортных средств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fbd601c501eac97934bdcd54d4761984121dc455bcb92a3f3a9355192108f498"},{"code_id":"GK_RF_2","article_number":"650","version_date":"1994-11-30","article_text":"1. По договору аренды здания или сооружения арендодатель обязуется передать во временное владение и пользование или во временное пользование арендатору здание или сооружение.\n\n2. Правила настоящего параграфа применяются к аренде предприятий, если иное не предусмотрено правилами настоящего Кодекса об аренде предприятия.","article_title":"Статья 650. Договор аренды здания или сооружения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ddcbdcb8d5228c2daab19a86a923765397df9b1ead123a160c535c2bc1697307"},{"code_id":"GK_RF_2","article_number":"651","version_date":"1994-11-30","article_text":"1. Договор аренды здания или сооружения заключается в письменной форме путем составления одного документа, подписанного сторонами (пункт 2 статьи 434).\n\nНесоблюдение формы договора аренды здания или сооружения влечет его недействительность.\n\n2. Договор аренды здания или сооружения, заключенный на срок не менее года, подлежит государственной регистрации и считается заключенным с момента такой регистрации.","article_title":"Статья 651. Форма и государственная регистрация договора аренды здания или сооружения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86cb650e45dcf4a9b92c512ae7443b07e90e15a12f3877876c927cf657460938"},{"code_id":"GK_RF_2","article_number":"652","version_date":"1994-11-30","article_text":"Если договором не определено передаваемое арендатору право на соответствующий земельный участок, к нему переходит на срок аренды здания или сооружения право пользования земельным участком, который занят зданием или сооружением и необходим для его использования в соответствии с его назначением. (В редакции Федерального закона от 26.06.2007 № 118-ФЗ)","article_title":"Статья 652. Права на земельный участок при аренде находящегося на нем здания или сооружения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e33f7274ce24c850673f867fe52efe5dfb380efbbe7091a3a77c6fbd2082310d"},{"code_id":"GK_RF_2","article_number":"653","version_date":"1994-11-30","article_text":"В случаях, когда земельный участок, на котором находится арендованное здание или сооружение, продается другому лицу, за арендатором этого здания или сооружения сохраняется право пользования земельным участком, который занят зданием или сооружением и необходим для его использования, на условиях, действовавших до продажи земельного участка. (В редакции Федерального закона от 26.06.2007 № 118-ФЗ)","article_title":"Статья 653. Сохранение арендатором здания или сооружения права пользования земельным участком при его продаже","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fcea3e57c017fa9c390ae886108ca883b9b1ce58519ecd962e10051838d7b02a"},{"code_id":"GK_RF_2","article_number":"654","version_date":"1994-11-30","article_text":"1. Договор аренды здания или сооружения должен предусматривать размер арендной платы. При отсутствии согласованного сторонами в письменной форме условия о размере арендной платы договор аренды здания или сооружения считается незаключенным. При этом правила определения цены, предусмотренные пунктом 3 статьи 424 настоящего Кодекса, не применяются.\n\n2. Установленная в договоре аренды здания или сооружения плата за пользование зданием или сооружением включает плату за пользование земельным участком, на котором оно расположено, или передаваемой вместе с ним соответствующей частью участка, если иное не предусмотрено законом или договором.\n\n3. В случаях, когда плата за аренду здания или сооружения установлена в договоре на единицу площади здания (сооружения) или иного показателя его размера, арендная плата определяется исходя из фактического размера переданного арендатору здания или сооружения.","article_title":"Статья 654. Размер арендной платы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7f164e4c0e8f22a305d18876e98b2a095fd0ad497886da3a8561c44ab4efe3dc"},{"code_id":"GK_RF_2","article_number":"655","version_date":"1994-11-30","article_text":"1. Передача здания или сооружения арендодателем и принятие его арендатором осуществляются по передаточному акту или иному документу о передаче, подписываемому сторонами.\n\nЕсли иное не предусмотрено законом или договором аренды здания или сооружения, обязательство арендодателя передать здание или сооружение арендатору считается исполненным после предоставления его арендатору во владение или пользование и подписания сторонами соответствующего документа о передаче.\n\nУклонение одной из сторон от подписания документа о передаче здания или сооружения на условиях, предусмотренных договором, рассматривается как отказ соответственно арендодателя от исполнения обязанности по передаче имущества, а арендатора от принятия имущества.\n\n2. При прекращении договора аренды здания или сооружения арендованное здание или сооружение должно быть возвращено арендодателю с соблюдением правил, предусмотренных пунктом 1 настоящей статьи.","article_title":"Статья 655. Передача здания или сооружения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"720eacb14a1149f66ac8b40bb20d20c3052195596f894f6dc8ea223ad31bed0f"},{"code_id":"GK_RF_2","article_number":"657","version_date":"1994-11-30","article_text":"1. Кредиторы по обязательствам, включенным в состав предприятия, должны быть до его передачи арендатору письменно уведомлены арендодателем о передаче предприятия в аренду.\n\n2. Кредитор, который письменно не сообщил арендодателю о своем согласии на перевод долга, вправе в течение трех месяцев со дня получения уведомления о передаче предприятия в аренду потребовать прекращения и\n\nли досрочного исполнения обязательства и возмещения причиненных этим убытков.\n\n3. Кредитор, который не был уведомлен о передаче предприятия в аренду в порядке, предусмотренном пунктом 1 настоящей статьи, может предъявить иск об удовлетворении требований, предусмотренных пунктом 2 настоящей статьи, в течение года со дня, когда он узнал или должен был узнать о передаче предприятия в аренду.\n\n4. После передачи предприятия в аренду арендодатель и арендатор несут солидарную ответственность по включенным в состав переданного предприятия долгам, которые были переведены на арендатора без согласия кредитора.","article_title":"Статья 657. Права кредиторов при аренде предприятия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1cce175e089874aca49b106e39df16b8773eb5d63c3c273cc5ee92d227b16a3e"},{"code_id":"GK_RF_2","article_number":"658","version_date":"1994-11-30","article_text":"1. Договор аренды предприятия заключается в письменной форме путем составления одного документа, подписанного сторонами (пункт 2 статьи 434).\n\n2. Договор аренды предприятия подлежит государственной регистрации и считается заключенным с момента такой регистрации.\n\n3. Несоблюдение формы договора аренды предприятия влечет его недействительность.","article_title":"Статья 658. Форма и государственная регистрация договора аренды предприятия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fdcdb19e034b2a765500e9a588baef10bc4527168fe908cc9a79d7643fce1f0d"},{"code_id":"GK_RF_2","article_number":"659","version_date":"1994-11-30","article_text":"Передача предприятия арендатору осуществляется по передаточному акту.\n\nПодготовка предприятия к передаче, включая составление и представление на подписание передаточного акта, является обязанностью арендодателя и осуществляется за его счет, если иное не предусмотрено договором аренды предприятия.","article_title":"Статья 659. Передача арендованного предприятия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c7125546a08159962239d5a83776578d38d9b377088121203c513b91aa28497f"},{"code_id":"GK_RF_2","article_number":"660","version_date":"1994-11-30","article_text":"Если иное не предусмотрено договором аренды предприятия, арендатор вправе без согласия арендодателя продавать, обменивать, предоставлять во временное пользование либо взаймы материальные ценности, входящие в состав имущества арендованного предприятия, сдавать их в субаренду и передавать свои права и обязанности по договору аренды в отношении таких ценностей другому лицу при условии, что это не влечет уменьшения стоимости предприятия и не нарушает других положений договора аренды предприятия. Указанный порядок не применяется в отношении земли и других природных ресурсов, а также в иных случаях, предусмотренных законом.\n\nЕсли иное не предусмотрено договором аренды предприятия, арендатор вправе без согласия арендодателя вносить изменения в состав арендованного имущественного комплекса, проводить его реконструкцию, расширение, техническое перевооружение, увеличивающее его стоимость.","article_title":"Статья 660. Пользование имуществом арендованного предприятия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2cf70097213eb4ab34ed96180e2aef8443acdb92da112a78fee1d7e181283450"},{"code_id":"GK_RF_2","article_number":"661","version_date":"1994-11-30","article_text":"1. Арендатор предприятия обязан в течение всего срока действия договора аренды предприятия поддерживать предприятие в надлежащем техническом состоянии, в том числе осуществление его текущего и капитального ремонта.\n\n2. На арендатора возлагаются расходы, связанные с эксплуатацией арендованного предприятия, если иное не предусмотрено договором, а также с уплатой платежей по страхованию арендованного имущества.","article_title":"Статья 661. Обязанности арендатора по содержанию предприятия и оплате расходов на его эксплуатацию","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ab35d942ef84e7c813114a2b3b61985c01a97c76d4daa533afe2d21d38d1bd0e"},{"code_id":"GK_RF_2","article_number":"662","version_date":"1994-11-30","article_text":"Арендатор предприятия имеет право на возмещение ему стоимости неотделимых улучшений арендованного имущества независимо от разрешения арендодателя на такие улучшения, если иное не предусмотрено договором аренды предприятия.\n\nАрендодатель может быть освобожден судом от обязанности возместить арендатору стоимость таких улучшений, если докажет, что издержки арендатора на эти улучшения повышают стоимость арендованного имущества несоразмерно улучшению его качества и (или) эксплуатационных свойств или при осуществлении таких улучшений были нарушены принципы добросовестности и разумности.","article_title":"Статья 662. Внесение арендатором улучшений в арендованное предприятие","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"041539031afc219a43091756c75d00357452b00cd0e27c28333e9ac4c0ba5632"},{"code_id":"GK_RF_2","article_number":"663","version_date":"1994-11-30","article_text":"Правила настоящего Кодекса о последствиях недействительности сделок, об изменении и о расторжении договора, предусматривающие возврат или взыскание в натуре полученного по договору с одной стороны или с обеих сторон, применяются к договору аренды предприятия, если такие последствия не нарушают существенно права и охраняемые законом интересы кредиторов арендодателя и арендатора, других лиц и не противоречат общественным интересам.","article_title":"Статья 663. Применение к договору аренды предприятия правил о последствиях недействительности сделок, об изменении и о расторжении договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a83b7124259dae6e573b4694b07b2820bb40a5d1f490856b48e4af122e9f0f3"},{"code_id":"GK_RF_2","article_number":"664","version_date":"1994-11-30","article_text":"При прекращении договора аренды предприятия арендованный имущественный комплекс должен быть возвращен арендодателю с соблюдением правил, предусмотренных статьями 656, 657 и 659 настоящего Кодекса. Подготовка предприятия к передаче арендодателю, включая составление и представление на подписание передаточного акта, является в этом случае обязанностью арендатора и осуществляется за его счет, если иное не предусмотрено договором.","article_title":"Статья 664. Возврат арендованного предприятия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b389f39be541d761b7b2633bb53f9ac7465427100fcdcb3278c5c71a5bec122b"},{"code_id":"GK_RF_2","article_number":"665","version_date":"1994-11-30","article_text":"По договору финансовой аренды (договору лизинга) арендодатель обязуется приобрести в собственность указанное арендатором имущество у определенного им продавца и предоставить арендатору это имущество за плату во временное владение и пользование. Арендодатель в этом случае не несет ответственности за выбор предмета аренды и продавца. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nДоговором финансовой аренды может быть предусмотрено, что выбор продавца и приобретаемого имущества осуществляется арендодателем.\n\nЧасть. (Дополнение частью - Федеральный закон от 08.05.2010 № 83-ФЗ) (Утратила силу - Федеральный закон от 31.12.2014 № 512-ФЗ)\n\nОсобенности договора финансовой аренды (договора лизинга), заключаемого государственным или муниципальным учреждением, устанавливаются Федеральным законом от 29 октября 1998 года № 164-ФЗ \"О финансовой аренде (лизинге)\".  (Дополнение частью - Федеральный закон от 31.12.2014 № 512-ФЗ)","article_title":"Статья 665. Договор финансовой аренды","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"616f940c6108751220bf2976b659f76df461101e509e8530b7b1a9636f182f42"},{"code_id":"GK_RF_2","article_number":"666","version_date":"1994-11-30","article_text":"Предметом договора финансовой аренды могут быть любые непотребляемые вещи, кроме земельных участков и других природных объектов. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)","article_title":"Статья 666. Предмет договора финансовой аренды","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"960ae10fc708d424000db33855bc664ab33b090700736d983a266d1c46d85715"},{"code_id":"GK_RF_2","article_number":"667","version_date":"1994-11-30","article_text":"Арендодатель, приобретая имущество для арендатора, должен уведомить продавца о том, что имущество предназначено для передачи его в аренду определенному лицу.","article_title":"Статья 667. Уведомление продавца о сдаче имущества в аренду","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"28dfe76785b62a09e6ab12c31e8cee33418d79fe4d7547324edda50d7da4dbea"},{"code_id":"GK_RF_2","article_number":"668","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором финансовой аренды, имущество, являющееся предметом этого договора, передается продавцом непосредственно арендатору в месте нахождения последнего.\n\n2. В случае, когда имущество, являющееся предметом договора финансовой аренды, не передано арендатору в указанный в этом договоре срок, а если в договоре такой срок не указан, в разумный срок, арендатор вправе, если просрочка допущена по обстоятельствам, за которые отвечает арендодатель, потребовать расторжения договора и возмещения убытков.","article_title":"Статья 668. Передача арендатору предмета договора финансовой аренды","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"91b34d92056bc6f76041101d160b85d85914415f4f8a3a1efd90858f8cb9c323"},{"code_id":"GK_RF_2","article_number":"669","version_date":"1994-11-30","article_text":"Риск случайной гибели или случайной порчи арендованного имущества переходит к арендатору в момент передачи ему арендованного имущества, если иное не предусмотрено договором финансовой аренды.","article_title":"Статья 669. Переход к арендатору риска случайной гибели или случайной порчи имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ac6941fd03d230e0652a755e7f15eceeb14aefcb01bcb3508354f99626e7bfd8"},{"code_id":"GK_RF_2","article_number":"670","version_date":"1994-11-30","article_text":"1. Арендатор вправе предъявлять непосредственно продавцу имущества, являющегося предметом договора финансовой аренды, требования, вытекающие из договора купли-продажи, заключенного между продавцом и арендодателем, в частности в отношении качества и комплектности имущества, сроков его поставки, и в других случаях ненадлежащего исполнения договора продавцом. При этом арендатор имеет права и несет обязанности, предусмотренные настоящим Кодексом для покупателя, кроме обязанности оплатить приобретенное имущество, как если бы он был стороной договора купли-продажи указанного имущества. Однако арендатор не может расторгнуть договор купли-продажи с продавцом без согласия арендодателя.\n\nВ отношениях с продавцом арендатор и арендодатель выступают как солидарные кредиторы (статья 326).\n\n2. Если иное не предусмотрено договором финансовой аренды, арендодатель не отвечает перед арендатором за выполнение продавцом требований, вытекающих из договора купли-продажи, кроме случаев, когда ответственность за выбор продавца лежит на арендодателе. В последнем случае арендатор вправе по своему выбору предъявлять требования, вытекающие из договора купли-продажи, как непосредственно продавцу имущества, так и арендодателю, которые несут солидарную ответственность.","article_title":"Статья 670. Ответственность продавца","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"10cf7a550832a2cf05a37989413d1399889c506a02c84b220007e7b6d3b492ce"},{"code_id":"GK_RF_2","article_number":"671","version_date":"1994-11-30","article_text":"1. По договору найма жилого помещения одна сторона - собственник жилого помещения или управомоченное им лицо (наймодатель) - обязуется предоставить другой стороне (нанимателю) жилое помещение за плату во владение и пользование для проживания в нем.\n\n2. Юридическим лицам жилое помещение может быть предоставлено во владение и (или) пользование на основе договора аренды или иного договора. Юридическое лицо может использовать жилое помещение только для проживания граждан.","article_title":"Статья 671. Договор найма жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0f95ec62f605fe07835c2a26f1af9d9079c26a682397f8d75cad72b199ec09eb"},{"code_id":"GK_RF_2","article_number":"672","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 21.07.2014 № 217-ФЗ)\n\nПо требованию нанимателя и членов его семьи договор может быть заключен с одним из членов семьи. В случае смерти нанимателя или его выбытия из жилого помещения договор заключается с одним из членов семьи, проживающих в жилом помещении.","article_title":"Статья 672. Договор найма жилого помещения в жилищном фонде социального использования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"108aa5ebbb9673e948cca7aa8c0da5394943b4a0c6115c6315e40a4b2bb5e87a"},{"code_id":"GK_RF_2","article_number":"673","version_date":"1994-11-30","article_text":"1. Объектом договора найма жилого помещения может быть изолированное жилое помещение, пригодное для постоянного проживания (квартира, жилой дом, часть квартиры или жилого дома).\n\nПригодность жилого помещения для проживания определяется в порядке, предусмотренном жилищным законодательством.\n\n2. Наниматель жилого помещения в многоквартирном доме наряду с пользованием жилым помещением имеет право пользоваться имуществом, указанным в статье 290 настоящего Кодекса.","article_title":"Статья 673. Объект договора найма жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2c97ad227598987be90c3ee8bbc5259c0c34697c768b6f6215fafd7fca8bfefb"},{"code_id":"GK_RF_2","article_number":"675","version_date":"1994-11-30","article_text":"Переход права собственности на занимаемое по договору найма жилое помещение не влечет расторжения или изменения договора найма жилого помещения. При этом новый собственник становится наймодателем на условиях ранее заключенного договора найма.","article_title":"Статья 675. Сохранение договора найма жилого помещения при переходе права собственности на жилое помещение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0c0d2793c126a6b8d09abc65a451ef61f1a664b7af65e80889d5e1e5610fe879"},{"code_id":"GK_RF_2","article_number":"676","version_date":"1994-11-30","article_text":"1. Наймодатель обязан передать нанимателю свободное жилое помещение в состоянии, пригодном для проживания.\n\n2. Наймодатель обязан осуществлять надлежащую эксплуатацию жилого дома, в котором находится сданное внаем жилое помещение, предоставлять или обеспечивать предоставление нанимателю за плату необходимых коммунальных услуг, обеспечивать проведение ремонта общего имущества многоквартирного дома и устройств для оказания коммунальных услуг, находящихся в жилом помещении.","article_title":"Статья 676. Обязанности наймодателя жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"79be0f549fc4b5455f45fbcd998ce5788bcbc7b0fd5f2e2bbf3d9adf56caa82a"},{"code_id":"GK_RF_2","article_number":"677","version_date":"1994-11-30","article_text":"1. Нанимателем по договору найма жилого помещения может быть только гражданин.\n\n2. В договоре должны быть указаны граждане, постоянно проживающие в жилом помещении вместе с нанимателем. При отсутствии в договоре таких указаний вселение этих граждан производится в соответствии с правилами статьи 679 настоящего Кодекса.\n\nГраждане, постоянно проживающие совместно с нанимателем, имеют равные с ним права по пользованию жилым помещением. Отношения между нанимателем и такими гражданами определяются законом.\n\n3. Наниматель несет ответственность перед наймодателем за действия граждан, постоянно проживающих совместно с ним, которые нарушают условия договора найма жилого помещения.\n\n4. Граждане, постоянно проживающие вместе с нанимателем, могут, известив наймодателя, заключить с нанимателем договор о том, что все граждане, постоянно проживающие в жилом помещении, несут совместно с нанимателем солидарную ответственность перед наймодателем. В этом случае такие граждане являются сонанимателями.","article_title":"Статья 677. Наниматель и постоянно проживающие вместе с ним граждане","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"38459c1117fdab69950ecf2c8321232c8635660cafba899f23c3d96516774f99"},{"code_id":"GK_RF_2","article_number":"678","version_date":"1994-11-30","article_text":"Наниматель обязан использовать жилое помещение только для проживания, обеспечивать сохранность жилого помещения и поддерживать его в надлежащем состоянии.\n\nНаниматель не вправе производить переустройство и реконструкцию жилого помещения без согласия наймодателя.\n\nНаниматель обязан своевременно вносить плату за жилое помещение. Если договором не установлено иное, наниматель обязан самостоятельно вносить коммунальные платежи.","article_title":"Статья 678. Обязанности нанимателя жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"08b0acbfbfe666630445522a15f6cacc49b5713f65df84ca81447d31767961fc"},{"code_id":"GK_RF_2","article_number":"679","version_date":"1994-11-30","article_text":"С согласия наймодателя, нанимателя и граждан, постоянно с ним проживающих, в жилое помещение могут быть вселены другие граждане в качестве постоянно проживающих с нанимателем. При вселении несовершеннолетних детей такого согласия не требуется.\n\nВселение допускается при условии соблюдения требований законодательства о норме общей площади жилого помещения на одного человека, кроме случая вселения несовершеннолетних детей. (В редакции Федерального закона от 29.12.2004 № 189-ФЗ)","article_title":"Статья 679. Вселение граждан, постоянно проживающих с нанимателем","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dc3fbf19a495c9b003ec290ed8c2806a5f576e3fc638b6a6af544cea141c794c"},{"code_id":"GK_RF_2","article_number":"680","version_date":"1994-11-30","article_text":"Наниматель и граждане, постоянно с ним проживающие, по общему согласию и с предварительным уведомлением наймодателя вправе разрешить безвозмездное проживание в жилом помещении временным жильцам (пользователям). Наймодатель может запретить проживание временных жильцов при условии несоблюдения требований законодательства о норме общей площади жилого помещения на одного человека. Срок проживания временных жильцов не может превышать шесть месяцев.  (В редакции Федерального закона от 29.12.2004 № 189-ФЗ)\n\nВременные жильцы не обладают самостоятельным правом пользования жилым помещением. Ответственность за их действия перед наймодателем несет наниматель.\n\nВременные жильцы обязаны освободить жилое помещение по истечении согласованного с ними срока проживания, а если срок не согласован, не позднее семи дней со дня предъявления соответствующего требования нанимателем или любым гражданином, постоянно с ним проживающим.","article_title":"Статья 680. Временные жильцы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0ac77810b4f057bcd49d1c982f1a594487e2e8054d764d9fc680c3b7e8348c0c"},{"code_id":"GK_RF_2","article_number":"681","version_date":"1994-11-30","article_text":"1. Текущий ремонт сданного внаем жилого помещения является обязанностью нанимателя, если иное не установлено договором найма жилого помещения.\n\n2. Капитальный ремонт сданного внаем жилого помещения является обязанностью наймодателя, если иное не установлено договором найма жилого помещения.\n\n3. Переоборудование жилого дома, в котором находится сданное внаем жилое помещение, если такое переоборудование существенно изменяет условия пользования жилым помещением, без согласия нанимателя не допускается.","article_title":"Статья 681. Ремонт сданного внаем жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"90e657192cb880b7c459f315c63dd24e449b5390d65c38b9c9fbdfc5b5498caf"},{"code_id":"GK_RF_2","article_number":"682","version_date":"1994-11-30","article_text":"1. Размер платы за жилое помещение устанавливается по соглашению сторон в договоре найма жилого помещения. В случае, если в соответствии с законом установлен максимальный размер платы за жилое помещение, плата, установленная в договоре, не должна превышать этот размер.\n\n2. Одностороннее изменение размера платы за жилое помещение не допускается, за исключением случаев, предусмотренных законом или договором.\n\n3. Плата за жилое помещение должна вноситься нанимателем в сроки, предусмотренные договором найма жилого помещения. Если договором сроки не предусмотрены, плата должна вноситься нанимателем ежемесячно в порядке, установленном Жилищным кодексом Российской Федерации.","article_title":"Статья 682. Плата за жилое помещение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"53f45ada2d64cfcda3a3d7018cc43bc1790dd8ae46f5353a521657d62621678d"},{"code_id":"GK_RF_2","article_number":"683","version_date":"1994-11-30","article_text":"1. Договор найма жилого помещения заключается на срок, не превышающий пяти лет. Если в договоре срок не определен, договор считается заключенным на пять лет.\n\n2. К договору найма жилого помещения, заключенному на срок до одного года (краткосрочный наем), не применяются правила, предусмотренные пунктом 2 статьи 677, статьями 680, 684 - 686, абзацем четвертым пункта 2 статьи 687 настоящего Кодекса, если договором не предусмотрено иное.","article_title":"Статья 683. Срок в договоре найма жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3a141bcc53b9f2c229ebdd66310a8f15d4860ba82e829a7fd9d8ee6c08132117"},{"code_id":"GK_RF_2","article_number":"684","version_date":"1994-11-30","article_text":"По истечении срока договора найма жилого помещения наниматель имеет преимущественное право на заключение договора найма жилого помещения на новый срок.\n\nНе позднее чем за три месяца до истечения срока договора найма жилого помещения наймодатель должен предложить нанимателю заключить договор на тех же или иных условиях либо предупредить нанимателя об отказе от продления договора в связи с решением не сдавать в течение не менее года жилое помещение внаем. Если наймодатель не выполнил этой обязанности, а наниматель не отказался от продления договора, договор считается продленным на тех же условиях и на тот же срок.\n\nПри согласовании условий договора наниматель не вправе требовать увеличения числа лиц, постоянно с ним проживающих по договору найма жилого помещения.\n\nЕсли наймодатель отказался от продления договора в связи с решением не сдавать помещение внаем, но в течение года со дня истечения срока договора с нанимателем заключил договор найма жилого помещения с другим лицом, наниматель вправе требовать признания такого договора недействительным и (или) возмещения убытков, причиненных отказом возобновить с ним договор.","article_title":"Статья 684. Преимущественное право нанимателя на заключение договора на новый срок","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6e31d4de0ec2deb1dcd56853adfd38c48a1bc8df5e9b1f723c2b42a6f50cd14"},{"code_id":"GK_RF_2","article_number":"685","version_date":"1994-11-30","article_text":"1. По договору поднайма жилого помещения наниматель с согласия наймодателя передает на срок часть или все нанятое им помещение в пользование поднанимателю. Поднаниматель не приобретает самостоятельного права пользования жилым помещением. Ответственным перед наймодателем по договору найма жилого помещения остается наниматель.\n\n2. Договор поднайма жилого пом\n\nещения может быть заключен при условии соблюдения требований законодательства о норме общей площади жилого помещения на одного человека. (В редакции Федерального закона от 29.12.2004 № 189-ФЗ)\n\n3. Договор поднайма жилого помещения является возмездным.\n\n4. Срок договора поднайма жилого помещения не может превышать срока договора найма жилого помещения.\n\n5. При досрочном прекращении договора найма жилого помещения одновременно с ним прекращается договор поднайма жилого помещения.\n\n6. На договор поднайма жилого помещения не распространяются правила о преимущественном праве на заключение договора на новый срок.","article_title":"Статья 685. Поднаем жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4aefcc5ffd69a23a6cbe9fdbacbe3f79b5e5a63fd4cd7408e1a2ef04464b4ee9"},{"code_id":"GK_RF_2","article_number":"686","version_date":"1994-11-30","article_text":"1. По требованию нанимателя и других граждан, постоянно с ним проживающих, и с согласия наймодателя наниматель в договоре найма жилого помещения может быть заменен одним из совершеннолетних граждан, постоянно проживающих с нанимателем.\n\n2. В случае смерти нанимателя или его выбытия из жилого помещения договор продолжает действовать на тех же условиях, а нанимателем становится один из граждан, постоянно проживающих с прежним нанимателем, по общему согласию между ними. Если такое согласие не достигнуто, все граждане, постоянно проживающие в жилом помещении, становятся сонанимателями.","article_title":"Статья 686. Замена нанимателя в договоре найма жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f496751f2741559630e26c784804069f5519ba5241c657dc76052cfff36d7dfe"},{"code_id":"GK_RF_2","article_number":"687","version_date":"1994-11-30","article_text":"1. Наниматель жилого помещения вправе с согласия других граждан, постоянно проживающих с ним, в любое время расторгнуть договор найма с письменным предупреждением наймодателя за три месяца.\n\n2. Договор найма жилого помещения может быть расторгнут в судебном порядке по требованию наймодателя в случаях:\n\nневнесения нанимателем платы за жилое помещение за шесть месяцев, если договором не установлен более длительный срок, а при краткосрочном найме в случае невнесения платы более двух раз по истечении установленного договором срока платежа;\n\nразрушения или порчи жилого помещения нанимателем или другими гражданами, за действия которых он отвечает.\n\nПо решению суда нанимателю может быть предоставлен срок не более года для устранения им нарушений, послуживших основанием для расторжения договора найма жилого помещения. Если в течение определенного судом срока наниматель не устранит допущенных нарушений или не примет всех необходимых мер для их устранения, суд по повторному обращению наймодателя принимает решение о расторжении договора найма жилого помещения. При этом по просьбе нанимателя суд в решении о расторжении договора может отсрочить исполнение решения на срок не более года.\n\n3. Договор найма жилого помещения может быть расторгнут в судебном порядке по требованию любой из сторон в договоре:\n\nесли помещение перестает быть пригодным для постоянного проживания, а также в случае его аварийного состояния;\n\nв других случаях, предусмотренных жилищным законодательством.\n\n4. Если наниматель жилого помещения или другие граждане, за действия которых он отвечает, используют жилое помещение не по назначению либо систематически нарушают права и интересы соседей, наймодатель может предупредить нанимателя о необходимости устранения нарушения.\n\nЕсли наниматель или другие граждане, за действия которых он отвечает, после предупреждения продолжают использовать жилое помещение не по назначению или нарушать права и интересы соседей, наймодатель вправе в судебном порядке расторгнуть договор найма жилого помещения. В этом случае применяются правила, предусмотренные абзацем четвертым пункта 2 настоящей статьи.","article_title":"Статья 687. Расторжение договора найма жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d7eb715936932db23755a65039c32d2d05b079ffacde35e9d2d48b94732e767e"},{"code_id":"GK_RF_2","article_number":"688","version_date":"1994-11-30","article_text":"В случае расторжения договора найма жилого помещения наниматель и другие граждане, проживающие в жилом помещении к моменту расторжения договора, подлежат выселению из жилого помещения на основании решения суда.","article_title":"Статья 688. Последствия расторжения договора найма жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"45ca8371316ada3395a668ddc0126c5f452ca928a53159d88bfa1de2f7699411"},{"code_id":"GK_RF_2","article_number":"689","version_date":"1994-11-30","article_text":"1. По договору безвозмездного пользования (договору ссуды) одна сторона (ссудодатель) обязуется передать или передает вещь в безвозмездное временное пользование другой стороне (ссудополучателю), а последняя обязуется вернуть ту же вещь в том состоянии, в каком она ее получила, с учетом нормального износа или в состоянии, обусловленном договором.\n\n2. К договору безвозмездного пользования соответственно применяются правила, предусмотренные статьей 607, пунктом 1 и абзацем первым пункта 2 статьи 610, пунктами 1 и 3 статьи 615, пунктом 2 статьи 621, пунктами 1 и 3 статьи 623 настоящего Кодекса.","article_title":"Статья 689. Договор безвозмездного пользования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"01451094f24a4e3626ab97257c62f7e9507925ddb2b2e21e87fa032cd32c1395"},{"code_id":"GK_RF_2","article_number":"690","version_date":"1994-11-30","article_text":"1. Право передачи вещи в безвозмездное пользование принадлежит ее собственнику и иным лицам, управомоченным на то законом или собственником.\n\n2. Коммерческая организация не вправе передавать имущество в безвозмездное пользование лицу, являющемуся ее учредителем, участником, руководителем, членом ее органов управления или контроля.","article_title":"Статья 690. Ссудодатель","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"355735012cbca138242c70ba470dcb11cae001c624f19a6c8ff0744b59c894ab"},{"code_id":"GK_RF_2","article_number":"691","version_date":"1994-11-30","article_text":"1. Ссудодатель обязан предоставить вещь в состоянии, соответствующем условиям договора безвозмездного пользования и ее назначению.\n\n2. Вещь предоставляется в безвозмездное пользование со всеми ее принадлежностями и относящимися к ней документами (инструкцией по использованию, техническим паспортом и т.п.), если иное не предусмотрено договором.\n\nЕсли такие принадлежности и документы переданы не были, однако без них вещь не может быть использована по назначению либо ее использование в значительной степени утрачивает ценность для ссудополучателя, последний вправе потребовать предоставления ему таких принадлежностей и документов либо расторжения договора и возмещения понесенного им реального ущерба.","article_title":"Статья 691. Предоставление вещи в безвозмездное пользование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7142ef59ac247a47147477536f4812d1019039f6f356ddcc63cf8e49043ec9d6"},{"code_id":"GK_RF_2","article_number":"692","version_date":"1994-11-30","article_text":"Если ссудодатель не передает вещь ссудополучателю, последний вправе потребовать расторжения договора безвозмездного пользования и возмещения понесенного им реального ущерба.","article_title":"Статья 692. Последствия непредоставления вещи в безвозмездное пользование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bd7eff78d5a0ce6c7f43dd9850bb70f23ce263dede2ad58e69db3e821b31a2c9"},{"code_id":"GK_RF_2","article_number":"693","version_date":"1994-11-30","article_text":"1. Ссудодатель отвечает за недостатки вещи, которые он умышленно или по грубой неосторожности не оговорил при заключении договора безвозмездного пользования.\n\nПри обнаружении таких недостатков ссудополучатель вправе по своему выбору потребовать от ссудодателя безвозмездного устранения недостатков вещи или возмещения своих расходов на устранение недостатков вещи либо досрочного расторжения договора и возмещения понесенного им реального ущерба.\n\n2. Ссудодатель, извещенный о требованиях ссудополучателя или о его намерении устранить недостатки вещи за счет ссудодателя, может без промедления произвести замену неисправной вещи другой аналогичной вещью, находящейся в надлежащем состоянии.\n\n3. Ссудодатель не отвечает за недостатки вещи, которые были им оговорены при заключении договора, либо были заранее известны ссудополучателю, либо должны были быть обнаружены ссудополучателем во время осмотра вещи или проверки ее исправности при заключении договора или при передаче вещи.","article_title":"Статья 693. Ответственность за недостатки вещи, переданной в безвозмездное пользование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8d766c25a1a03a1e9c7eb107a830e1c83247cd41e6657c4d800ff590615021d5"},{"code_id":"GK_RF_2","article_number":"694","version_date":"1994-11-30","article_text":"Передача вещи в безвозмездное пользование не является основанием для изменения или прекращения прав третьих лиц на эту вещь.\n\nПри заключении договора безвозмездного пользования ссудодатель обязан предупредить ссудополучателя о всех правах третьих лиц на эту вещь (сервитуте, праве залога и т.п.). Неисполнение этой обязанности дает ссудополучателю право требовать расторжения договора и возмещения понесенного им реального ущерба.","article_title":"Статья 694. Права третьих лиц на вещь, передаваемую в безвозмездное пользование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"633e0408a72af10d65b381bbc0f1dd5c5bab385f2c3b7810bae7b2cabbbb8bba"},{"code_id":"GK_RF_2","article_number":"695","version_date":"1994-11-30","article_text":"Ссудополучатель обязан поддерживать вещь, полученную в безвозмездное пользование, в исправном состоянии, включая осуществление текущего и капитального ремонта, и нести все расходы на ее содержание, если иное не предусмотрено договором безвозмездного пользования.","article_title":"Статья 695. Обязанности ссудополучателя по содержанию вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4379e7acf1c9728b5839fc2a1c159a4ced2414a05d0b1c823b242748ba30db66"},{"code_id":"GK_RF_2","article_number":"696","version_date":"1994-11-30","article_text":"Ссудополучатель несет риск случайной гибели или случайного повреждения полученной в безвозмездное пользование вещи, если вещь погибла или была испорчена в связи с тем, что он использовал ее не в соответствии с договором безвозмездного пользования или назначением вещи либо передал ее третьему лицу без согласия ссудодателя. Ссудополучатель несет также риск случайной гибели или случайного повреждения вещи, если с учетом фактических обстоятельств мог предотвратить ее гибель или порчу, пожертвовав своей вещью, но предпочел сохранить свою вещь.","article_title":"Статья 696. Риск случайной гибели или случайного повреждения вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"456c4c084e04f734d295a98b07251b7c4a5346a133f1be454d3464d6c1b77cb0"},{"code_id":"GK_RF_2","article_number":"697","version_date":"1994-11-30","article_text":"Ссудодатель отвечает за вред, причиненный третьему лицу в результате использования вещи, если не докажет, что вред причинен вследствие умысла или грубой неосторожности ссудополучателя или лица, у которого эта вещь оказалась с согласия ссудодателя.","article_title":"Статья 697. Ответственность за вред, причиненный третьему лицу в результате использования вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f8d1459d7530590c6ac8dc8cf060c2bf24e6a7d842ca63886d1403d9fcfdc0f3"},{"code_id":"GK_RF_2","article_number":"698","version_date":"1994-11-30","article_text":"1. Ссудодатель вправе потребовать досрочного расторжения договора безвозмездного пользования в случаях, когда ссудополучатель:\n\nиспользует вещь не в соответствии с договором или назначением вещи;\n\nне выполняет обязанностей по поддержанию вещи в исправном состоянии или ее содержанию;\n\nсущественно ухудшает состояние вещи;\n\nбез согласия ссудодателя передал вещь третьему лицу.\n\n2. Ссудополучатель вправе требовать досрочного расторжения договора безвозмездного пользования:\n\nпри обнаружении недостатков, делающих нормальное использование вещи невозможным или обременительным, о наличии которых он не знал и не мог знать в момент заключения договора;\n\nесли вещь в силу обстоятельств, за которые он не отвечает, окажется в состоянии, непригодном для использования;\n\nесли при заключении договора ссудодатель не предупредил его о правах третьих лиц на передаваемую вещь;\n\nпри неисполнении ссудодателем обязанности передать вещь либо ее принадлежности и относящиеся к ней документы.","article_title":"Статья 698. Досрочное расторжение договора безвозмездного пользования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e186610abab44fc30f1cd2dab341052b87098bc4ff6a5772095f946b8d4b60d9"},{"code_id":"GK_RF_2","article_number":"699","version_date":"1994-11-30","article_text":"1. Каждая из сторон вправе во всякое время отказаться от договора безвозмездного пользования, заключенного без указания срока, известив об этом другую сторону за один месяц, если договором не предусмотрен иной срок извещения.\n\n2. Если иное не предусмотрено договором, ссудополучатель вправе во всякое время отказаться от договора, заключенного с указанием срока, в порядке, предусмотренном пунктом 1 настоящей статьи.","article_title":"Статья 699. Отказ от договора безвозмездного пользования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a17e3c7044c6324523fbefadae63211f9bc0986defc01fae715c93ab03b2aecf"},{"code_id":"GK_RF_2","article_number":"700","version_date":"1994-11-30","article_text":"1. Ссудодатель вправе произвести отчуждение вещи или передать ее в возмездное пользование третьему лицу. При этом к новому собственнику или пользователю переходят права по ранее заключенному договору безвозмездного пользования, а его права в отношении вещи обременяются правами ссудополучателя.\n\n2. В случае смерти гражданина-ссудодателя либо реорганизации или ликвидации юридического лица - ссудодателя права и обязанности ссудодателя по договору безвозмездного пользования переходят к наследнику (правопреемнику) или к другому лицу, к которому перешло право собственности на вещь или иное право, на основании которого вещь была передана в безвозмездное пользование.\n\nВ случае реорганизации юридического лица - ссудополучателя его права и обязанности по договору переходят к юридическому лицу, являющемуся его правопреемником, если иное не предусмотрено договором.","article_title":"Статья 700. Изменение сторон в договоре безвозмездного пользования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"99bfa6cf33b3c7711f2fd3e9ea7e3607277778c9dd2b0ff9075a3c8baee87a00"},{"code_id":"GK_RF_2","article_number":"701","version_date":"1994-11-30","article_text":"Договор безвозмездного пользования прекращается в случае смерти гражданина-ссудополучателя или ликвидации юридического лица - ссудополучателя, если иное не предусмотрено договором.","article_title":"Статья 701. Прекращение договора безвозмездного пользования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"af5bbb16119f98997d1e6c1cfbc1767ce1f1c3dd7d28a0ec4d5f18c5cb073ce5"},{"code_id":"GK_RF_2","article_number":"702","version_date":"1994-11-30","article_text":"1. По договору подряда одна сторона (подрядчик) обязуется выполнить по заданию другой стороны (заказчика) определенную работу и сдать ее результат заказчику, а заказчик обязуется принять результат работы и оплатить его.\n\n2. К отдельным видам договора подряда (бытовой подряд, строительный подряд, подряд на выполнение проектных и изыскательских работ, подрядные работы для государственных нужд) положения, предусмотренные настоящим параграфом, применяются, если иное не установлено правилами настоящего Кодекса об этих видах договоров.","article_title":"Статья 702. Договор подряда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8a8a6ddec695963f78a95d3586623919f014f15af204c88a89ec7431e754bd9a"},{"code_id":"GK_RF_2","article_number":"703","version_date":"1994-11-30","article_text":"1. Договор подряда заключается на изготовление или переработку (обработку) вещи либо на выполнение другой работы с передачей ее результата заказчику.\n\n2. По договору подряда, заключенному на изготовление вещи, подрядчик передает права на нее заказчику.\n\n3. Если иное не предусмотрено договором, подрядчик самостоятельно определяет способы выполнения задания заказчика.","article_title":"Статья 703. Работы, выполняемые по договору подряда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"03e19830d8c42cf1a6de0a89232d271ab09f7c2b1fc2eec1ab35d2f1a454e4dd"},{"code_id":"GK_RF_2","article_number":"704","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором подряда, работа выполняется иждивением подрядчика - из его материалов, его силами и средствами.\n\n2. Подрядчик несет ответственность за ненадлежащее качество предоставленных им материалов и оборудования, а также за предоставление материалов и оборудования, обремененных правами третьих лиц.","article_title":"Статья 704. Выполнение работы иждивением подрядчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c0bd77108fa5d5a21c8f0caae4c5601cc73f66aad9c35c25030af72e11127541"},{"code_id":"GK_RF_2","article_number":"705","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено настоящим Кодексом, иными законами или договором подряда:\n\nриск случайной гибели или случайного повреждения материалов, оборудования, переданной для переработки (обработки) вещи или иного используемого для исполнения договора имущества несет предоставившая их сторона;\n\nриск случайной гибели или случайного повреждения результата выполненной работы до ее приемки заказчиком несет подрядчик.\n\n2. При просрочке передачи или приемки результата работы риски, предусмотренные в пункте 1 настоящей статьи, несет сторона, допустившая просрочку.","article_title":"Статья 705. Распределение рисков между сторонами","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0aa1f64e34fb2dde8a080dd758f02ee3f35665f3188df81870618d6788228462"},{"code_id":"GK_RF_2","article_number":"706","version_date":"1994-11-30","article_text":"1. Если из закона или договора подряда не вытекает обязанность подрядчика выполнить предусмотренную в договоре работу лично, подрядчик вправе привлечь к исполнению своих обязательств других лиц (субподрядчиков). В этом случае подрядчик выступает в роли генерального подрядчика.\n\n2. Подрядчик, который привлек к исполнению договора подряда субподрядчика в нарушение положений пункта 1 настоящей статьи или договора, несет перед заказчиком ответственность за убытки, причиненные участием субподрядчика в исполнении договора.\n\n3. Генеральный подрядчик несет перед заказчиком ответственность за последствия неисполнения или ненадлежащего исполнения обязательств субподрядчиком в соответствии с правилами пункта 1 статьи 313 и статьи 403 настоящего Кодекса, а перед субподрядчиком - ответственность за неисполнение или ненадлежащее исполнение заказчиком обязательств по договору подряда.\n\nЕсли иное не предусмотрено законом или договором, заказчик и субподрядчик не вправе предъявлять друг другу требования, связанные с нарушением договоров, заключенных каждым из них с генеральным подрядчиком.\n\n4. С согласия генерального подрядчика заказчик вправе заключить договоры на выполнение отдельных работ с другими лицами. В этом случае указанные лица несут ответственность за неисполнение или ненадлежащее исполнение работы непосредственно перед заказчиком.","article_title":"Статья 706. Генеральный подрядчик и субподрядчик","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0184158fdf213d1d8f1a9c8cd57d3507c9443151ec277c0e2cb456505e3ba72f"},{"code_id":"GK_RF_2","article_number":"707","version_date":"1994-11-30","article_text":"1. Если на стороне подрядчика выступают одновременно два лица или более, при неделимости предмета обязательства они признаются по отношению к заказчику солидарными должниками и соответственно солидарными кредиторами.\n\n2. При делимости предмета обязательства, а также в других случаях, предусмотренных законом, иными правовыми актами или договором, каждое из указанных в пункте 1 настоящей статьи лиц приобретает права и несет обязанности по отношению к заказчику в пределах своей доли (статья 321).","article_title":"Статья 707. Участие в исполнении работы нескольких лиц","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0185be2b432c72dd0c3f8e77f71be758f792848ae00203bc7d9e41b0e030a865"},{"code_id":"GK_RF_2","article_number":"708","version_date":"1994-11-30","article_text":"1. В договоре подряда указываются начальный и конечный сроки выполнения работы. По согласованию между сторонами в договоре могут быть предусмотрены также сроки завершения отдельных этапов работы (промежуточные сроки).\n\nЕсли иное не установлено законом, иными правовыми актами или не предусмотрено договором, подрядчик несет ответственность за нарушение как начального и конечного, так и промежуточных сроков выполнения работы.\n\n2. Указанные в договоре подряда начальный, конечный и промежуточные сроки выполнения работы могут быть изменены в случаях и в порядке, предусмотренных договором.","article_title":"Статья 708. Сроки выполнения работы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0d61edbc5fc9ed001d2d4054f28d7ad9088e053ece8c901028fac0e437eca8eb"},{"code_id":"GK_RF_2","article_number":"709","version_date":"1994-11-30","article_text":"1. В договоре подряда указываются цена подлежащей выполнению работы или способы ее определения. При отсутствии в договоре таких указаний цена определяется в соответствии с пунктом 3 статьи 424 настоящего Кодекса.\n\n2. Цена в договоре подряда включает компенсацию издержек подрядчика и причитающееся ему вознаграждение.\n\n3. Цена работы может быть определена путем составления сметы.\n\nВ случае, когда работа выполняется в соответствии со сметой, составленной подрядчиком, смета приобретает силу и становится частью договора подряда с момента подтверждения ее заказчиком.\n\n4. Цена работы (смета) может быть приблизительной или твердой. При отсутствии других указаний в договоре подряда цена работы считается твердой.\n\n5. Если возникла необходимость в проведении дополнительных работ и по этой причине в существенном превышении определенной приблизительно цены работы, подрядчик обязан своевременно предупредить об этом заказчика. Заказчик, не согласившийся на превышение указанной в договоре подряда цены работы, вправе отказаться от договора. В этом случае подрядчик может требовать от заказчика уплаты ему цены за выполненную часть работы.\n\nПодрядчик, своевременно не предупредивший заказчика о необходимости превышения указанной в договоре цены работы, обязан выполнить договор, сохраняя право на оплату работы по цене, определенной в договоре.\n\n6. Подрядчик не вправе требовать увеличения твердой цены, а заказчик ее уменьшения, в том числе в случае, когда в момент заключения договора подряда исключалась возможность предусмотреть полный объем подлежащих выполнению работ или необходимых для этого расходов.\n\nПри существенном возрастании стоимости материалов и оборудования, предоставленных подрядчиком, а также оказываемых ему третьими лицами услуг, которые нельзя было предусмотреть при заключении договора, подрядчик имеет право требовать увеличения установленной цены, а при отказе заказчика выполнить это требование - расторжения договора в соответствии со статьей 451 настоящего Кодекса.","article_title":"Статья 709. Цена работы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8e0c9b853827c5396c88f0a14a72ca43e548a7ef78e02ba3e748988ffdffee2c"},{"code_id":"GK_RF_2","article_number":"710","version_date":"1994-11-30","article_text":"1. В случаях, когда фактические расходы подрядчика оказались меньше тех, которые учитывались при определении цены работы, подрядчик сохраняет право на оплату работ по цене, предусмотренной договором подряда, если заказчик не докажет, что полученная подрядчиком экономия повлияла на качество выполненных работ.\n\n2. В договоре подряда может быть предусмотрено распределение полученной подрядчиком экономии между сторонами.","article_title":"Статья 710. Экономия подрядчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0fc698abd2624c9240921126cb28aed80ca5b1586418f12b43a204a3ec8b8f19"},{"code_id":"GK_RF_2","article_number":"711","version_date":"1994-11-30","article_text":"1. Если договором п\n\nодряда не предусмотрена предварительная оплата выполненной работы или отдельных ее этапов, заказчик обязан уплатить подрядчику обусловленную цену после окончательной сдачи результатов работы при условии, что работа выполнена надлежащим образом и в согласованный срок, либо с согласия заказчика досрочно.\n\n2. Подрядчик вправе требовать выплаты ему аванса либо задатка только в случаях и в размере, указанных в законе или договоре подряда.","article_title":"Статья 711. Порядок оплаты работы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f7ee4be35b9f87cb8130e2fbb716fd44c1f33f619d425d44c8165f7f1bd9cb1a"},{"code_id":"GK_RF_2","article_number":"712","version_date":"1994-11-30","article_text":"При неисполнении заказчиком обязанности уплатить установленную цену либо иную сумму, причитающуюся подрядчику в связи с выполнением договора подряда, подрядчик имеет право на удержание в соответствии со статьями 359 и 360 настоящего Кодекса результата работ, а также принадлежащих заказчику оборудования, переданной для переработки (обработки) вещи, остатка неиспользованного материала и другого оказавшегося у него имущества заказчика до уплаты заказчиком соответствующих сумм.","article_title":"Статья 712. Право подрядчика на удержание","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5a4cc1cd64662f355295ab9ea8c73ca4e76526c38754f3d89ed357d12e7f27fe"},{"code_id":"GK_RF_2","article_number":"713","version_date":"1994-11-30","article_text":"1. Подрядчик обязан использовать предоставленный заказчиком материал экономно и расчетливо, после окончания работы представить заказчику отчет об израсходовании материала, а также возвратить его остаток либо с согласия заказчика уменьшить цену работы с учетом стоимости остающегося у подрядчика неиспользованного материала.\n\n2. Если результат работы не был достигнут либо достигнутый результат оказался с недостатками, которые делают его не пригодным для предусмотренного в договоре подряда использования, а при отсутствии в договоре соответствующего условия не пригодным для обычного использования, по причинам, вызванным недостатками предоставленного заказчиком материала, подрядчик вправе потребовать оплаты выполненной им работы.\n\n3. Подрядчик может осуществить право, указанное в пункте 2 настоящей статьи, в случае, если докажет, что недостатки материала не могли быть обнаружены при надлежащей приемке подрядчиком этого материала.","article_title":"Статья 713. Выполнение работы с использованием материала заказчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9e62e68760d424af9249575d4f3dc2a39b7054dccb5567f8f8697b559b7edc98"},{"code_id":"GK_RF_2","article_number":"714","version_date":"1994-11-30","article_text":"Подрядчик несет ответственность за несохранность предоставленных заказчиком материала, оборудования, переданной для переработки (обработки) вещи или иного имущества, оказавшегося во владении подрядчика в связи с исполнением договора подряда.","article_title":"Статья 714. Ответственность подрядчика за несохранность предоставленного заказчиком имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bdf9f9ef72c4860ac0dbfc25345af99ce0914fe58549f3944e44b2d382d98604"},{"code_id":"GK_RF_2","article_number":"715","version_date":"1994-11-30","article_text":"1. Заказчик вправе во всякое время проверять ход и качество работы, выполняемой подрядчиком, не вмешиваясь в его деятельность.\n\n2. Если подрядчик не приступает своевременно к исполнению договора подряда или выполняет работу настолько медленно, что окончание ее к сроку становится явно невозможным, заказчик вправе отказаться от исполнения договора и потребовать возмещения убытков.\n\n3. Если во время выполнения работы станет очевидным, что она не будет выполнена надлежащим образом, заказчик вправе назначить подрядчику разумный срок для устранения недостатков и при неисполнении подрядчиком в назначенный срок этого требования отказаться от договора подряда либо поручить исправление работ другому лицу за счет подрядчика, а также потребовать возмещения убытков.","article_title":"Статья 715. Права заказчика во время выполнения работы подрядчиком","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ba7776cf84f1a7ff0dcfe9d4c5a7dfb887dce32cd738e61f59c9b2f162d5be51"},{"code_id":"GK_RF_2","article_number":"716","version_date":"1994-11-30","article_text":"1. Подрядчик обязан немедленно предупредить заказчика и до получения от него указаний приостановить работу при обнаружении:\n\nнепригодности или недоброкачественности предоставленных заказчиком материала, оборудования, технической документации или переданной для переработки (обработки) вещи;\n\nвозможных неблагоприятных для заказчика последствий выполнения его указаний о способе исполнения работы;\n\nиных не зависящих от подрядчика обстоятельств, которые грозят годности или прочности результатов выполняемой работы либо создают невозможность ее завершения в срок.\n\n2. Подрядчик, не предупредивший заказчика об обстоятельствах, указанных в пункте 1 настоящей статьи, либо продолживший работу, не дожидаясь истечения указанного в договоре срока, а при его отсутствии разумного срока для ответа на предупреждение или несмотря на своевременное указание заказчика о прекращении работы, не вправе при предъявлении к нему или им к заказчику соответствующих требований ссылаться на указанные обстоятельства.\n\n3. Если заказчик, несмотря на своевременное и обоснованное предупреждение со стороны подрядчика об обстоятельствах, указанных в пункте 1 настоящей статьи, в разумный срок не заменит непригодные или недоброкачественные материал, оборудование, техническую документацию или переданную для переработки (обработки) вещь, не изменит указаний о способе выполнения работы или не примет других необходимых мер для устранения обстоятельств, грозящих ее годности, подрядчик вправе отказаться от исполнения договора подряда и потребовать возмещения причиненных его прекращением убытков.","article_title":"Статья 716. Обстоятельства, о которых подрядчик обязан предупредить заказчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6ae0d5eac2790de5f1af57843c1bcedfb841c5fb46cb817d5c2f592faff944db"}]$law7d0034$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
